mapper.sql:
e.deleted_at IS NULL
AND e.employee_no LIKE CONCAT( '%', #{condition.employeeNo}, '%' )
AND e.employee_name LIKE CONCAT( '%', #{condition.employeeName}, '%' )
AND e.work_status = #{condition.workStatusCode}
AND e.sales_user_id = #{condition.salesUserId}
AND e.nearest_station LIKE CONCAT( '%', #{condition.nearestStation}, '%' )
AND EXISTS ( SELECT 1 FROM employee_skills es_filter WHERE es_filter.employee_id = e.employee_id AND es_filter.skill_id = #{condition.skillId} AND es_filter.deleted_at IS NULL
AND es_filter.experience_months >= #{condition.minExperienceMonths}
)
AND EXISTS ( SELECT 1 FROM assignments a_filter WHERE a_filter.employee_id = e.employee_id AND a_filter.assignment_status = '02' AND a_filter.contract_end_date IS NOT NULL AND a_filter.contract_end_date >= CURRENT_DATE AND a_filter.contract_end_date <= DATE_ADD( CURRENT_DATE, INTERVAL #{condition.endWithinDays} DAY ) AND a_filter.deleted_at IS NULL )

mapper.update:
UPDATE interviews
SET deleted_at = CURRENT_TIMESTAMP,
    updated_by = #{loginUserId}
WHERE employee_id = #{employeeId}
  AND deleted_at IS NULL

UPDATE assignments
SET deleted_at = CURRENT_TIMESTAMP,
    updated_by = #{loginUserId}
WHERE employee_id = #{employeeId}
  AND deleted_at IS NULL

UPDATE employee_skills
SET deleted_at = CURRENT_TIMESTAMP,
    updated_by = #{loginUserId}
WHERE employee_id = #{employeeId}
  AND deleted_at IS NULL

UPDATE employees
SET deleted_at = CURRENT_TIMESTAMP,
    updated_by = #{loginUserId}
WHERE employee_id = #{employeeId}
  AND deleted_at IS NULL
